// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address newOwner, bool succeed) public {
        vm.assume(newOwner != c.owner());
        vm.prank(c.owner());
        bool ok;
        try c.transferOwnership(newOwner) { ok = true; } catch { ok = false; }
        vm.assume(succeed);
        vm.assume(ok);
        assertTrue(c.owner() == newOwner);
    }
}
